function validate([n, start]) {
  if (!Number.isInteger(n) || n < 1 || n > 1000) return 'n is an integer between 1 and 1000.';
  if (!Number.isInteger(start) || start < 0 || start > 1000) return 'start is an integer between 0 and 1000.';
  return null;
}

