function xorOperation(n, start) {
  const prefixXor = (x) => {
    if (x < 0) return 0;
    const rest = x % 4;
    if (rest === 0) return x;
    if (rest === 1) return 1;
    if (rest === 2) return x + 1;
    return 0;
  };

  const half = start >> 1;
  const high = prefixXor(half + n - 1) ^ prefixXor(half - 1);
  const low = start & n & 1;
  return (high << 1) | low;
}

